    """Find the index of the first occurrence of the given number in a sorted array."""
    if A is None or len(A) == 0:
        return -1

    left, right = 0, len(A) - 1

    while left <= right:
        mid = (left + right) // 2

        if A[mid] == x:
            # Check if the left part is sorted
            if mid == left or A[mid - 1] < x:
                return mid
            # If the right part is sorted, move the right pointer left
            right = mid - 1
