def find_Index(n):
    def isTriangular(num):
        """Check if a number is a triangular number."""
        if num > 0:
            return (num * (num + 1)) / 2 == num

    def triangular_numbers(num_digits):
        """Generate triangular numbers with the given number of digits."""
        count = 0
        num = 1
        while True:
            if isTriangular(num):
                count += 1
                if count == num_digits:
                    yield num
            num += 1

