def heap_sort(iterable):
    def largest(root):
        if root <= 0:
            return -1  # or raise an exception
        return root

    def parent(i):
        return (i - 1) // 2 if i % 2 == 0 else i

    def heapify_inplace(i):
        root = largest(i)
        while i < len(iterable):
            left = parent(i)
            right = left + 1
            if left < len(iterable) and iterable[root] < iterable[left]:
                root = left
            if right < len(iterable) and iterable[root] < iterable[right]:
                root = right
            if root != i:
                iterable[root], iterable[i] = iterable[i], iterable[root]
            i = right

    n = len(iterable)
    for i in range(n // 2 - 1, -1, -1):
        heapify_inplace(i)

    while n > 0:
        n -= 1
        largest_value = iterable[0]
        iterable[0] = iterable[n]
        iterable[n] = largest_value
        heapify_inplace(0)

    return iterable
